) AS (
  VALUES 
    (86::BIGINT, 'Los que comentan mal de él es porque fijo ni iban a clase o no le ponían. Este es de los mejores profes que he tenido en el tec, demasiado buena nota, no lo piense dos veces para llevar con él. Es el balance perfecto entre aprender bien sin que le regalen el curso ni que lo califiquen a matar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Clases excelentes']::TEXT[], '2026-06-16T00:00:00+00:00'::TIMESTAMPTZ, '8bc3b036fafa190f8a2ddec1ae282fa0f8298f57d63a399927b84f4a7a054196'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Buen profesor. Las clases suelen ser un poco aburridas, sin embargo, las presentaciones del profesor son muy buenas para repasar. Además, se hacen ejercicios en clase que ayudan mucho para los quices y exámenes. El proyecto es interesante por la simulación en COMSOL.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2026-01-10T00:00:00+00:00'::TIMESTAMPTZ, '7d17923d93e7c798aa7ee2b8d7eb459ad3dcbd73df126642c68d37df8ac86ab1'::TEXT, ARRAY[2740]::BIGINT[]),
    (86::BIGINT, 'Peor profe que tuve, más vago que quien sabe que, el aspecto de los trabajos en grupo diay es mixto porque a mi me tocó un grupo de malas personas, los exámenes un relajo, lee puro PowerPoint y es de esos que explica haciendo rápido el ejercicio NO la materia. Evítenlo para no llevarse colochos.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'dc56149e09de3041a609dca4d9c0f0b5f4e5f36f4d5798017ddf43d098316a57'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Muy buena nota el profe, se pasa facil con hacer todos los informes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '299011fee4ffb787f02be8867481e234e3f95a1fa5d6c1e602f42a954e824f87'::TEXT, ARRAY[938]::BIGINT[]),
    (86::BIGINT, 'Excelente profesor, el curso se pasa relativamente fácil. Las clases son extremadamente largas, pero se aprende. Enseña excel y matlab, en el primer examen uno decide qué usa. Lo más importante: consiga un buen grupo de trabajo y mínimo que alguno sepa programar. No pasa lista, pero trate de ir.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2025-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'd626c5c9fd6752779b2dec36ed14441b14447a1b3ef8d546bbdca4cd395f6b1b'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Si no son de la carrera de Ing en Materiales no pierdan su tiempo matriculando con él, solo le interesan los estudiantes de carrera, además no explica terminología necesaria "porque ya la tuvieron que ver en cursos anteriores" y si uno pide ayuda primero atiende a los de materiales.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2025-07-03T00:00:00+00:00'::TIMESTAMPTZ, '531e81b7d532fb4a21f75391ec77a5f59636914670a780cf530b2ef4877f3e83'::TEXT, ARRAY[1895]::BIGINT[]),
    (86::BIGINT, 'Buen profe, creo que de los mejores para métodos, ya que le gusta esa área. Enseña con Excel y Matlab, casi todo se programa en clase y da buen tiempo para eso. Nada más asegúrese de tener buen equipo de trabajo ya que las 3 tareas + el último examen son en grupo. Se sale en semana 18.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, '3cca7707920fab6f0ff8192489e224272f314676647aa8904266546e4fdd8dbb'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Un profe 100% recomendado, en serio no falte a clases porque aunque puedan llegar a ser aburridas, en serio se aprende demasiado y se avanza para las tareas, el profe explica muy claro y se asegura de que todos vayan con él y tengan todo claro. Los exámenes son fáciles si va a clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'd2c077e19711b3c2fe0f170f229b691df12341c1bb93973f68040d218d47ec5c'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Curso colchon con el, todo es virtual hasta el examen. Se pasa solo, no se aprende nada, pero es un curso gratis, ni siquiera hay que ir y se pasa con 100'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'fd3adb30ffe6a44a6ce2fbdf4f49a85a3539eebdd12a597a39980911916e98c3'::TEXT, ARRAY[1205]::BIGINT[]),
    (86::BIGINT, 'Un profesor muy amable y claro, explica super bien y las veces que sea necesario. La mayoría de tareas se hacen o adelantan en clases, además hay mucho material de apoyo, lo único es que a veces las clases se hacen medio aburridas, pero igualmente vale la pena'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2023-07-13T00:00:00+00:00'::TIMESTAMPTZ, '9a87c60e1d34fc44d4826ec206156786a45995e3dd0973a562636b3d3150d7c9'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Es super amable y explica las veces que se ocupe. Los exámenes y tareas se hacen con lo que se vio en clase. Ayuda un montón.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '6e01a75d36f3e302bb0a90d84902db8784ee0e210578ea9aec1189eca5f59799'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Como dijo mi ex, métalo sin miedo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '7372e15116fcb260847d8a32443e4e64cb2983eb7b4f41c4900ceed71946f4f1'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Las clases son sumamente largas y algo aburridas, pero también es por la materia. Realmente se aprende bastante con él. Ojalá conseguir un buen grupo de trabajo para las tareas programadas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-05-27T00:00:00+00:00'::TIMESTAMPTZ, '5e3f260aab176329de9b290446a40006ab741b291fcfa3fbe473802ec0677b1e'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Super amable y dispuesto a ayudar. Da muy buena retroalimentacion para el proyecto y hasta lo dirije a uno a por donde preguntar o investigar. Tiene un somnífero en la boca eso si, las clases son bastante aburridas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Brinda apoyo']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, '802251b1b94b6efad5f4b3d5887643f42e9e828165674bd573ab49979d59ee1f'::TEXT, ARRAY[1205]::BIGINT[]),
    (86::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, '8ae79834427353715f7b679b20f983641f25c89e531ad55bd4cfa688d0f9b514'::TEXT, ARRAY[1205]::BIGINT[]),
    (86::BIGINT, 'Super facil un 100 asegurado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-27T00:00:00+00:00'::TIMESTAMPTZ, '82d537792be36032a4c27fcd38f9024fdcd79213aafb34c12c37b263c77b8d07'::TEXT, ARRAY[2806, 2746, 2807, 2741, 2805, 2766, 2756, 2803]::BIGINT[]),
    (86::BIGINT, 'Para Ciencias de los Materiales es la mejor opción. Exámenes y tareas sencillas. El curso fácilmente se pasa con 100.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '8e04221a2f85315e2e9b7e5d3bbc89f5d72e4afa932c03339e502591f1a8348e'::TEXT, ARRAY[1205]::BIGINT[]),
    (86::BIGINT, 'Es un 10/10 como profe, las evaluaciones son muy sencillas, se sacan fácilmente con lo visto en clase. Sin embargo las progras si se complican un poquito más, como recomendación siempre vaya a consulta, el ayuda mucho si nota su interés. Ojo con los exámenes, no se confíe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-16T00:00:00+00:00'::TIMESTAMPTZ, '9b198f8b9aa96fd5acceae436d77b8938aa8d6bac69d6ee3b1113cd50d106f09'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Solamente fui a clases en Semana 1 y pasé con 100 el curso. Los exámenes son muy fáciles y califica muy suave el proyecto. Lo recomiendo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'b6a014735fc60d8b0bd70e858f9db29d0513cf8032dab7baf22b389df6a233da'::TEXT, ARRAY[1205]::BIGINT[]),
    (86::BIGINT, 'Si no sabe bien como programar no lleven con él. No explica nada bien, bueno no explica nada más evalua.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2022-01-12T00:00:00+00:00'::TIMESTAMPTZ, '8e8b0b7cf5fae831a164583048a8892cb27866a7b9ddd02f0c01d5c6b1470315'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Muy tuanis el profe y muy fácil pasar con él. Lo único es que la materia es un poco aburridilla. Pero igual hay que llevar el curso, súper recomendado el profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '0fe5a43177780ea1179a8f8ec128ab0f6e32f20d77a98fba17a0092bc07b6679'::TEXT, ARRAY[1205]::BIGINT[]),
    (86::BIGINT, 'Clases muy aburridas, uno se puede llegar a perder fácil pero es muy organizado con subir las clases entonces si uno se perdió en algún lado lo revisa veloz. El curso es fácil y con él más. Ayuda bastante y en lo que uno guste.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, '5b61f098445bec433cc18230de5d9b2d2acd1b025149d56e8620abcffa9d335c'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'El profe es super buena nota y ayuda en lo que pueda. Las clases son bastante aburridas y uno se puede peder fácil pero si logra poner atención entiende. Las tareas importantes y un examen son en grupo entonces eso es escencial'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, '309eef0bc2040bc54e8df065af99dfd53f6b8426e94f65239dd10defa120b1ac'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'El curso se pasa solo, el profe explica bastante bien y además las evaluaciones son demasiado fáciles. Las respuestas de los parciales son textuales de las diapositivas y revisa muy suave el proyecto.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '32e54913f0f9d7e8dca3134ed62f9490ec54ee15ed602b8192ed402ae95ef10c'::TEXT, ARRAY[1205]::BIGINT[]),
    (86::BIGINT, 'El profe es muy consiente con el estudiante, los exámenes son fáciles y se aprende bien. Muy buen profesor y persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2021-07-07T00:00:00+00:00'::TIMESTAMPTZ, '43f12caf3bb26b2dd59bc1f386e2610bf7b1385a88a6458f6a74e673b03e5881'::TEXT, ARRAY[1205]::BIGINT[]),
    (86::BIGINT, 'El curso no es lo que uno espera, pero con este profe se pasa súper fácil, explica muy bien, los exámenes son fáciles y comprende mucho al estudiante, por lo que deja pocas asignaciones y bastante tiempo para resolverlas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, '0ea6ae7292fc6f4d36651033878bd32c3a7af4e954c9a94df1d260469d4f1290'::TEXT, ARRAY[1205]::BIGINT[]),
    (86::BIGINT, '(virtual) el profe es super buena persona, ayuda demasiado, tiene muy buena voluntad, lo único es que el curso como tal no es bonito pero el profe es el mejor'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, '392c1cab6a3a91ff84bf9d8146fd6712ebaecc68e19fadeb8259f5e6ca6e93a7'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, '20/10 El compa es increíble, tareas dem cortas, responde dudas súper rápido, los exámenes son muy similares a lo que se ve en clases. Asistencia no es obligatoria. Meta con él porfi'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '4e8ac15d9f37efaf8a107590ae9ba13b23d9c69024efa5c56627172444deccca'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Diay mae, este mae es un dios de la pedagogía, entiende por completo a los estudiantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '03d4326489490832f15975806b88ccc0804dc415ecca97c0267940ceb1b8972b'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'No lo dude, meta con él. Se realizan varias tareas MUY cortas que se resuelven solas con lo que el profe explica en clase, hay 3 tareas de Matlab que se realizan en grupos y dos exámenes (uno individual y otro grupal). Recomendado al 100%. El curso el profe lo hace sencillo y se aprende bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '14d516f24e7e18c7fec9d57c367172dfc564369c759b10c2b04aa344fa76d105'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Excelente profesor, en consulta ayuda mucho. Las evaluaciones son claras y fáciles. Se le notan las ganas de que el estudiante aprenda y le vaya bien en el curso. A él lo que le importa es que usted aprenda y no tanto la nota o hacer las cosas para que usted se quede.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'd4c6afcebd25611d0c3ee74b657a2d6add422fa2ad16ee53882c209f56d5b612'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Dos examenes y 4 quices individuales, 4 tareas grupales. Explica todo super claro y es muy accesible para la entrega de todo. Se preocupa por que se aprenda. La parte de programar le toca a cada quien por su cuenta, pero por lo demás es excelente. De lo mejor que hay en materiales'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '7946b7692f932742398db3d17f9da676d113eccce032bda5ecb4a63df75b6304'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'La clase llega a hacerse un poco larga pero todo queda muy claro, muy buen profe!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'ae166b019394418d600eea836e1fc7e048623e4b870f4e2ab8cd2f01ac3876ca'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Explica muy claro, solo hay que poner atención en clase. La clase dura aprox. 1hr y media (sincrónica), sin trabajo asincrónico. Deja 4 tareas programadas en grupo y 2 examenes para la casa, fácil salir bien. Ayuda mucho. Aprender Matlab le toca al estudiante, él da una pincelada nada más. Es crack.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '720627754f4dd13809ad3fbcb89989a7edee03c18f75f5a86b31e00ddac5f290'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Es un muy buen profesor, quizá la voz es un poco aburrida y las clases son un poco largas. Pero luego de eso, explica muy bien, es muy flexible, ayuda muchísimo y deja todo súper claro. No se van a arrepentir de matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2020-08-15T00:00:00+00:00'::TIMESTAMPTZ, '56e71bef4eabf5f440b44d7760ed54d86d30f242cb848c616ce922754909a14b'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Excelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2020-08-06T00:00:00+00:00'::TIMESTAMPTZ, 'f260fff000f047638a165892386050f09cd14f035517ad99d04d59b415115433'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Muy agradable y ayuda mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-05-14T00:00:00+00:00'::TIMESTAMPTZ, '9c26c8dbe4238d24681f610e6f7a4e8c814be3151d5188516d6caa30d926c20d'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'No pasa lista, enseña de la forma en que el aprendió y esto facilita bastante las cosas. Siempre le resuelve las dudas a uno, así le pregunte varias veces, el profe siempre va a explicarle hasta que quede claro. No califica duro y es demasiado buena gente. Si puede meter el curso con él, dele de una'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, '73c858a4c00f9f3b052f5336cc84e23c861e614c2d35c19584cc4db5ee97aa7e'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Es excelente, enseña hasta la forma en la que él aprendió para que se vuelva más sencillo. Ayuda mucho. Abarca bien los temas, y es muy justo para calificar. Los quices y tareas siempre se parecen a los de semestres anteriores.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'e6c3d960df1d43735ae798a46022ae79a975576066522abe92f9a12159576c3f'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación']::TEXT[], '2019-10-09T00:00:00+00:00'::TIMESTAMPTZ, 'c33ae12e7b430e808daba6fd753b6acd2c829f525ef20b7082ef9bafd31e9607'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'El profe es una teja, se lleva demasiado con bien con los estudiantes y ayuda muchísimo, el curso se vuelve muy sencillo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes']::TEXT[], '2019-05-08T00:00:00+00:00'::TIMESTAMPTZ, 'ab801dbdfdc528f84f91ab59db0bac3402525654699bb7579585b6d14b443bca'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Demasiado facil, ayuda demasiado en quices y tareas para que uno tenga 100 en esos porcentajes. demasiado ABURRIDO otro nivel de aburrida la clase y como habla'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-31T00:00:00+00:00'::TIMESTAMPTZ, '56b6d87b4494f21955b069e441dc780319a8706815bc503f7eacd65a76e0a5c6'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Muy recomendado. Es un poco aburrido a veces pero explica excelente y es muy motivador. Realmente uno disfruta el curso y le encuentra verdadera utilidad (a veces incluso en otros cursos). Es muy comprensivo y ayuda mucho, además es muy pura vida y gracioso. De fijo llevaría más cursos con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-12-21T00:00:00+00:00'::TIMESTAMPTZ, '6e9aebb420587c1c6ff3326a52475d2ca2ae6a73708bf9fe56d72ce286b76c84'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Profe primerizo, pero muy atento al estudiante, dispuesto a ayudar y muy amigable. Da un poco de pereza como da las clases pero si uno no entiende el le ayuda. Los quices y las tareas son bastante fáciles y el segundo exámen lo deja para la casa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, '3b5ed5bc07953773dd32ba008c93a1eed51ac54c09e4b93d0d5a241bd7e2b61f'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Muy buen profesor. Las tareas se hacen en grupos y los quices son muy sencillos. El primer examen es parecido a los de semestres pasados y es escrito, pero el segundo se hace en matlab por lo que es recomendable hacerlo con un compañero si carece de experiencia en programación'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'ad6cd7f0b78cddfa61da1908f141edb09600406dd506482f2e9665bb7a6047fc'::TEXT, ARRAY[968]::BIGINT[]),
    (86::BIGINT, 'Da la materia sacándola del cuaderno de cuando él la llevó, es bastante apagado pero se nota que le pone bastante para tratar de dar la clase de la mejor manera. Fue la primera vez dando clases de él. Con respecto a tareas y exámenes, son muy accesibles y él ayuda.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos proyectos grupales']::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'f8d43f691212f76bf4cc04c973184df0078a37776dca4d24b5022399cfe5b579'::TEXT, ARRAY[968]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
